{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "System dynamics applications have also been used in areas related to upstream prevention efforts focusing on issues like nutrition, exercise, vaccinations, and tobacco control, in addition to downstream efforts in treatment and care [20-23]. Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Describes current knowledge of system dynamics applications in public health and related areas, and identifies uncertainties regarding cancer-specific use."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention. In a 2019 report, the National Academies of Sciences, Engineering, and Medicine argued that systems science methods could help illustrate the multilevel nature of cancer effects and costs to society and help cancer control efforts be more agile and adaptive [7]. The Journal of the National Cancer Institute published several reports calling for the use of complex, multilevel, or systems-focused approaches to advance the landscape of cancer prevention and control [1, 2, 10]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Explains the importance of systems approaches for cancer care and the need to review system dynamics applications due to existing gaps."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "Cites previous reviews in the field and explains the need for the current review due to lack of focus on cancer-specific applications."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not focused on intervention effects; it is a systematic review of modeling methods and applications."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not involve complex interventions or delivery contexts; it examines modeling approaches for cancer prevention and control."
    }
  ],
  "confidence": 90
}

